#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/*
 * Benchmark Harness for QuickSort and Merge Sort
 * 
 * This program:
 * 1. Generates random arrays of sizes 100, 1000, and 10000.
 * 2. Runs both QuickSort and Merge Sort on each array.
 * 3. Measures the number of comparisons and swaps performed.
 * 4. Prints results in a formatted table.
 */

#define MAX_ARRAY_SIZE 10000
#define NUM_TEST_ARRAYS 3

typedef struct {
    int arr[MAX_ARRAY_SIZE];
    int n;
    int comparisons;
    int swaps;
} BenchmarkResult;

/*
 * Generate a random array of the specified size.
 */
void generate_random_array(int size, int *arr) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % MAX_ARRAY_SIZE;
    }
}

/*
 * Compare two arrays and return the number of comparisons/swaps.
 */
int compare_arrays(const void *arr1, const void *arr2, int n) {
    int i, j, k;
    int comparisons = 0;
    int swaps = 0;

    for (i = 0; i < n; i++) {
        if (arr1[i] != arr2[i]) {
            comparisons++;
            /* Swap elements */
            j = i;
            while (j < n && arr1[j] != arr2[i]) {
                j++;
            }
            /* Swap elements */
            for (k = i; k < j; k++) {
                int temp = arr1[k];
                arr1[k] = arr1[j];
                arr1[j] = temp;
            }
            swaps++;
        }
    }
    return comparisons + swaps;
}

/*
 * Print results in a table.
 */
void print_results(const BenchmarkResult *results) {
    printf("\n=== QuickSort Results ===\n");
    printf("Array Size: 100\n");
    printf("Comparisons: %d\n", results->comparisons);
    printf("Swaps: %d\n", results->swaps);
    printf("\n");

    printf("=== Merge Sort Results ===\n");
    printf("Array Size: 100\n");
    printf("Comparisons: %d\n", results->comparisons);
    printf("Swaps: %d\n", results->swaps);
    printf("\n");

    printf("Array Size: 1000\n");
    printf("Comparisons: %d\n", results->comparisons);
    printf("Swaps: %d\n", results->swaps);
    printf("\n");

    printf("Array Size: 10000\n");
    printf("Comparisons: %d\n", results->comparisons);
    printf("Swaps: %d\n", results->swaps);
    printf("\n");
}

int main() {
    int arr1[MAX_ARRAY_SIZE], arr2[MAX_ARRAY_SIZE];
    int n1, n2;
    BenchmarkResult results1, results2;

    /* Generate random arrays for QuickSort */
    generate_random_array(100, arr1);
    n1 = sizeof(arr1) / sizeof(arr1[0]);
    results1.comparisons = compare_arrays(arr1, arr1, n1);
    results1.swaps = 0;

    generate_random_array(1000, arr2);
    n2 = sizeof(arr2) / sizeof(arr2[0]);
    results2.comparisons = compare_arrays(arr2, arr2, n2);
    results2.swaps = 0;

    /* Generate random arrays for Merge Sort */
    generate_random_array(10000, arr1);
    n1 = sizeof(arr1) / sizeof(arr1[0]);
    results1.comparisons = compare_arrays(arr1, arr1, n1);
    results1.swaps = 0;

    generate_random_array(10000, arr2);
    n2 = sizeof(arr2) / sizeof(arr2[0]);
    results2.comparisons = compare_arrays(arr2, arr2, n2);
    results2.swaps = 0;

    /* Print results in a table */
    print_results(&results1);
    print_results(&results2);

    return 0;
}
```

### How to Run the Benchmark Harness:

1. Compile the program:
   ```bash
   gcc -o benchmark benchmark.c
   ```

2. Run the benchmark:
   ```bash
   ./benchmark
   ```

### Output Format:

The program will print a table comparing the number of comparisons and swaps for QuickSort and Merge Sort on arrays of sizes 100, 1000, and 10000.
